window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2216dcea6773a4ed"]={"versions": [{"id": "FIG-2216dcea6773a4ed", "releases": ["R23-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitstrahldiagramm / Timing-Diagramm zur formalen Charakterisierung stochastischer und deterministischer Ereignismuster.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (TPS_TimingExtensions, Kapitel <em>Timing Description Model / Event Triggering</em>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Metamodell-Elements <code>PeriodicEventTriggering</code> (Spezialisierung von <code>EventTriggeringConstraint</code>). Das Schaubild visualisiert die mathematisch-zeitliche Korrelation zwischen Nennperiode (<code>period</code>), maximal zulässiger zeitlicher Abweichung (<code>jitter</code>) und dem resultierenden Worst-Case-Mindestabstand aufeinanderfolgender Ereignisse (<code>minimumInterArrivalTime</code>, MIAT).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metaklasse <code>PeriodicEventTriggering</code></strong> (Metamodell-Element in <code>AUTOSAR::TimingExtensions::TimingDescriptionModel</code>):\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimingCondition</code> bzw. assoziiert mit einem <code>TimingEvent</code> (z. B. Aktivierung einer Runnable Entity, PDU-Sendeanforderung oder Bus-Empfangsereignis).\n</li></ul>\n</li><li><strong>Attribute &amp; Datenstrukturen (Typ <code>MultidimensionalTime</code>):</strong>\n<ul class=\"fig-list\"><li><strong><code>period</code>:</strong> Nominale Zykluszeit/Wiederholrate des Ereignisses.\n</li><li><strong><code>jitter</code>:</strong> Zeitintervall, das die maximal zulässige Variation des Auslösezeitpunkts bezogen auf die periodischen Soll-Referenzzeitpunkte festlegt.\n</li><li><strong><code>minimumInterArrivalTime</code> (MIAT):</strong> Untere Schranke des zeitlichen Abstands zwischen zwei direkt aufeinanderfolgenden Ereignisinstanzen.\n</li></ul>\n</li><li><strong>Akteure / Ereignisinstanzen:</strong>\n<ul class=\"fig-list\"><li><strong><code>Event Occurrence</code> (n, n+1, n+2):</strong> Diskrete Triggerzeitpunkte eines beobachteten Events auf der Systemzeitleiste (<code>time</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nominale Referenzierung:</strong> Das System generiert äquidistante Soll-Zeitmarken im Abstand von T_period.\n</li><li><strong>Jitter-Fenster:</strong> Jedes Ereignis k darf innerhalb eines Aktivierungsfensters [t_nom, k, t_nom, k + Jitter] auftreten.\n</li><li><strong>Entstehung des Worst-Case-Burst (Minimaler Ankunftsabstand):</strong>\n<ol class=\"fig-list\"><li>Ereignis n erfährt maximale Latenz/Verzögerung und tritt am spätestmöglichen Rand seines Jitter-Fensters auf (t_n = t_nom, n + Jitter).\n</li><li>Ereignis n+1 wird unverzögert zum frühestmöglichen Zeitpunkt ausgelöst (t_n+1 = t_nom, n+1 = t_nom, n + Period).\n</li><li>Der reale zeitliche Abstand zwischen n und n+1 kollabiert auf das Minimum:\n $MIAT = Period - Jitter$\n</li><li>Ereignis n+2 tritt wieder mit Verzögerung innerhalb seines Fensters auf, wodurch sich der nachfolgende Abstand vergrößert.\n</li></ol>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- und OS-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Wenn eine Runnable Entity über ein periodisches <code>TimingEvent</code> mit Jitter aktiviert wird, darf die Task-Queue nicht überlaufen. Ein konfigurierter Jitter führt dazu, dass zwei Ausführungsanforderungen im Abstand von MIAT eintreffen.\n</li><li>Reicht die Ausführungszeit (WCET) der Runnable über MIAT hinaus, drohen Task-Aktivierungsverluste (<code>E_OS_LIMIT</code>) oder reentrante Aufrufe, falls keine ausreichende Warteschlangentiefe (OsTaskActivation / QueueLength) konfiguriert ist.\n</li></ul>\n</li><li><strong>Schedulability- &amp; Timing-Analyse:</strong>\n<ul class=\"fig-list\"><li>In formalen Timing-Verifikationen (z. B. SymTA/S, INCHRON Tool-Suite) transformiert das Paar (Period, Jitter) ein rein periodisches Modell in ein sporadisches Lastmodell mit Burst-Faktor.\n</li><li><strong>Konsistenzprüfung:</strong> Es muss normativ Jitter &lt; Period gelten, andernfalls sinkt MIAT ≤ 0, was zu simultanen Ereignissen (Event-Overlap) führt.\n</li></ul>\n</li><li><strong>Kommunikationsstack (Com / PduR / Treiber):</strong>\n<ul class=\"fig-list\"><li>Für zyklisch gesendete Botschaften (z. B. cyclic CAN-/Ethernet-PDUs) modelliert dieses Pattern das Sende-Jitter-Verhalten (verursacht durch ISR-Sperrzeiten, Bus-Arbitrierung oder Scheduling-Jitter der Com-MainFunction).\n</li><li>Empfangsseitig definiert MIAT die Auslegung von Ringpuffern in Treibern und <code>SoAd</code>/<code>Com</code>-Modulen, um Burst-Überläufe ohne Frame-Verlust verarbeiten zu können.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8b29cf25e8cf5bdb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Zeitstrahldiagramm / Timing-Diagramm zur formalen Charakterisierung stochastischer und deterministischer Ereignismuster.\n</li><li><strong>Architektur-Kontext:</strong> AUTOSAR Timing Extensions (TPS_TimingExtensions, Kapitel <em>Timing Description Model / Event Triggering</em>).\n</li><li><strong>Technischer Zweck:</strong> Formale Definition des Metamodell-Elements <code>PeriodicEventTriggering</code> (Spezialisierung von <code>EventTriggeringConstraint</code>). Das Schaubild visualisiert die mathematisch-zeitliche Korrelation zwischen Nennperiode (<code>period</code>), maximal zulässiger zeitlicher Abweichung (<code>jitter</code>) und dem resultierenden Worst-Case-Mindestabstand aufeinanderfolgender Ereignisse (<code>minimumInterArrivalTime</code>, MIAT).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Metaklasse <code>PeriodicEventTriggering</code></strong> (Metamodell-Element in <code>AUTOSAR::TimingExtensions::TimingDescriptionModel</code>):\n<ul class=\"fig-list\"><li>Aggregiert in <code>TimingCondition</code> bzw. assoziiert mit einem <code>TimingEvent</code> (z. B. Aktivierung einer Runnable Entity, PDU-Sendeanforderung oder Bus-Empfangsereignis).\n</li></ul>\n</li><li><strong>Attribute &amp; Datenstrukturen (Typ <code>MultidimensionalTime</code>):</strong>\n<ul class=\"fig-list\"><li><strong><code>period</code>:</strong> Nominale Zykluszeit/Wiederholrate des Ereignisses.\n</li><li><strong><code>jitter</code>:</strong> Zeitintervall, das die maximal zulässige Variation des Auslösezeitpunkts bezogen auf die periodischen Soll-Referenzzeitpunkte festlegt.\n</li><li><strong><code>minimumInterArrivalTime</code> (MIAT):</strong> Untere Schranke des zeitlichen Abstands zwischen zwei direkt aufeinanderfolgenden Ereignisinstanzen.\n</li></ul>\n</li><li><strong>Akteure / Ereignisinstanzen:</strong>\n<ul class=\"fig-list\"><li><strong><code>Event Occurrence</code> (n, n+1, n+2):</strong> Diskrete Triggerzeitpunkte eines beobachteten Events auf der Systemzeitleiste (<code>time</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nominale Referenzierung:</strong> Das System generiert äquidistante Soll-Zeitmarken im Abstand von T_period.\n</li><li><strong>Jitter-Fenster:</strong> Jedes Ereignis k darf innerhalb eines Aktivierungsfensters [t_nom, k, t_nom, k + Jitter] auftreten.\n</li><li><strong>Entstehung des Worst-Case-Burst (Minimaler Ankunftsabstand):</strong>\n<ol class=\"fig-list\"><li>Ereignis n erfährt maximale Latenz/Verzögerung und tritt am spätestmöglichen Rand seines Jitter-Fensters auf (t_n = t_nom, n + Jitter).\n</li><li>Ereignis n+1 wird unverzögert zum frühestmöglichen Zeitpunkt ausgelöst (t_n+1 = t_nom, n+1 = t_nom, n + Period).\n</li><li>Der reale zeitliche Abstand zwischen n und n+1 kollabiert auf das Minimum:\n $MIAT = Period - Jitter$\n</li><li>Ereignis n+2 tritt wieder mit Verzögerung innerhalb seines Fensters auf, wodurch sich der nachfolgende Abstand vergrößert.\n</li></ol>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE- und OS-Konfiguration:</strong>\n<ul class=\"fig-list\"><li>Wenn eine Runnable Entity über ein periodisches <code>TimingEvent</code> mit Jitter aktiviert wird, darf die Task-Queue nicht überlaufen. Ein konfigurierter Jitter führt dazu, dass zwei Ausführungsanforderungen im Abstand von MIAT eintreffen.\n</li><li>Reicht die Ausführungszeit (WCET) der Runnable über MIAT hinaus, drohen Task-Aktivierungsverluste (<code>E_OS_LIMIT</code>) oder reentrante Aufrufe, falls keine ausreichende Warteschlangentiefe (OsTaskActivation / QueueLength) konfiguriert ist.\n</li></ul>\n</li><li><strong>Schedulability- &amp; Timing-Analyse:</strong>\n<ul class=\"fig-list\"><li>In formalen Timing-Verifikationen (z. B. SymTA/S, INCHRON Tool-Suite) transformiert das Paar (Period, Jitter) ein rein periodisches Modell in ein sporadisches Lastmodell mit Burst-Faktor.\n</li><li><strong>Konsistenzprüfung:</strong> Es muss normativ Jitter &lt; Period gelten, andernfalls sinkt MIAT ≤ 0, was zu simultanen Ereignissen (Event-Overlap) führt.\n</li></ul>\n</li><li><strong>Kommunikationsstack (Com / PduR / Treiber):</strong>\n<ul class=\"fig-list\"><li>Für zyklisch gesendete Botschaften (z. B. cyclic CAN-/Ethernet-PDUs) modelliert dieses Pattern das Sende-Jitter-Verhalten (verursacht durch ISR-Sperrzeiten, Bus-Arbitrierung oder Scheduling-Jitter der Com-MainFunction).\n</li><li>Empfangsseitig definiert MIAT die Auslegung von Ringpuffern in Treibern und <code>SoAd</code>/<code>Com</code>-Modulen, um Burst-Überläufe ohne Frame-Verlust verarbeiten zu können.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2216dcea6773a4ed", "to": "FIG-8b29cf25e8cf5bdb", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8b29cf25e8cf5bdb", "to": "FIG-2216dcea6773a4ed", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
